WITH with_windows AS (SELECT *, ROW_NUMBER() OVER w_part AS event_seq, SUM(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, LAG(balance, 1) OVER (PARTITION BY account_type ORDER BY opened_date, id) AS prev_balance FROM accounts WINDOW w_part AS (PARTITION BY account_type ORDER BY balance, id)) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, ROUND(AVG(running_balance), 2) AS avg_running_balance, SIZE(COLLECT_SET(account_type)) AS num_account_types, MAX(prev_balance) AS max_prev_balance, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) AS frozen_count FROM with_windows GROUP BY DATE_TRUNC('YEAR', opened_date) HAVING max_prev_balance >= 0;
